-- Central UI templates (Master DB). Additive and idempotent; normal backend startup runs the same steps (ensureTemplates). Run as the knockout_master owner (the application role).
-- Existing tenants are assigned Classic. Take a backup first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(742918);
SET LOCAL search_path TO knockout_master, pg_catalog;
CREATE TABLE IF NOT EXISTS ui_templates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE CHECK (code ~ '^[a-z][a-z0-9_-]{1,39}$'),name VARCHAR(80) NOT NULL,version VARCHAR(20) NOT NULL DEFAULT '1.0.0' CHECK (version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'),active BOOLEAN NOT NULL DEFAULT TRUE,preview JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS template_assignments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NULL REFERENCES companies(id) ON DELETE SET NULL,company_name VARCHAR(160) NOT NULL,previous_template_id BIGINT NULL REFERENCES ui_templates(id),template_id BIGINT NOT NULL REFERENCES ui_templates(id),template_version VARCHAR(20) NOT NULL,assigned_by BIGINT NOT NULL,assigned_by_name VARCHAR(120) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO ui_templates (code,name,preview) VALUES
  ('classic','Classic','{"description":"The established KnockOUT workspace: dark sidebar, top bar and summary banner.","layout":"sidebar","colors":["#151719","#C5A572","#F8F7F4"]}'::jsonb),
  ('luxury','Luxury','{"description":"Editorial masthead with serif headlines, charcoal, champagne gold and warm ivory.","layout":"masthead","colors":["#2A2723","#B08D57","#FBF7EF"]}'::jsonb),
  ('modern','Modern','{"description":"Contemporary SaaS layout with a floating light sidebar and bento dashboard.","layout":"floating","colors":["#1D4ED8","#0F172A","#F3F6FB"]}'::jsonb),
  ('minimal','Minimal','{"description":"Monochrome and distraction-free: text navigation, hairlines and lists.","layout":"text","colors":["#111111","#8A8A8A","#FFFFFF"]}'::jsonb),
  ('royal','Royal','{"description":"Formal icon rail with deep navy, refined gold and framed panels.","layout":"rail","colors":["#0E1B3D","#C9A24B","#F5F3EC"]}'::jsonb)
ON CONFLICT (code) DO NOTHING;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS template_id BIGINT REFERENCES ui_templates(id);
UPDATE companies SET template_id=(SELECT id FROM ui_templates WHERE code='classic') WHERE template_id IS NULL;
DO $$ DECLARE classic BIGINT; BEGIN
  SELECT id INTO STRICT classic FROM ui_templates WHERE code='classic';
  EXECUTE format('ALTER TABLE companies ALTER COLUMN template_id SET DEFAULT %s, ALTER COLUMN template_id SET NOT NULL', classic);
END $$;
CREATE INDEX IF NOT EXISTS companies_template ON companies (template_id);
CREATE INDEX IF NOT EXISTS template_assignment_history ON template_assignments (company_id,id);
COMMIT;
-- Rollback (removes assignments): ALTER TABLE knockout_master.companies DROP COLUMN template_id; DROP TABLE knockout_master.template_assignments, knockout_master.ui_templates;
